const $=s=>document.querySelector(s), app=$('#app'), root=$('#modal-root');
const req=(id,el=id)=>`data-req-id="${id}" data-req-element="${el}"`;
const day=86400000, today=new Date(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})+'T00:00:00+08:00');
const add=(d,n)=>new Date(new Date(d).getTime()+n*day), fmt=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const profiles={frozen:{name:'王艳波',label:'身份冻结',subject:'重庆壹弘科技有限公司',id:'91500103MAE2CF7R62'},authentication:{name:'体验账号',label:'未认证',subject:'待认证主体',id:'—'},enterprise:{name:'王艳波',label:'企业',subject:'重庆壹弘科技有限公司',id:'91500103MAE2CF7R62'},personal:{name:'王三',label:'个人',subject:'王三',id:'5r0igj7a6gyaafjeg8'}};
const selectedType=()=>{const value=new URL(location.href).searchParams.get('user'),remembered=sessionStorage.getItem('cq-portal-user');return ['personal','enterprise','authentication','frozen'].includes(value)?value:['personal','enterprise','authentication','frozen'].includes(remembered)?remembered:'enterprise'};
let userType=selectedType();
const profile=()=>userType==='frozen'&&appeal?.status==='success'?{...profiles.frozen,label:'企业'}:profiles[userType], personal=()=>userType==='personal', frozen=()=>userType==='frozen';
let freezeBlocking=false,freezeForm=false,successNoticeOpen=false,appealTimer=null,appealTimerEpoch=0;
const appealStorageKey='cq-portal-freeze-appeal-v1';
let appeal;try{appeal=JSON.parse(localStorage.getItem(appealStorageKey))}catch{}
if(!['pending','success'].includes(appeal?.status)||appeal.subjectId!==profiles.frozen.id||typeof appeal.reason!=='string'||typeof appeal.phone!=='string')appeal=null;
let appealDraft={reason:'',phone:'18611740968'};
const frozenLocked=()=>frozen()&&appeal?.status!=='success';
const storageKey=()=>frozen()?'cq-portal-frozen-demo-v1':userType==='authentication'?'cq-portal-auth-demo-v1':personal()?'cq-portal-renewal-personal-v1':'cq-portal-renewal-v1';
const defaultState=()=>({created:fmt(add(today,-174)),expiry:fmt(add(today,6)),firstRenewal:null,pending:null});
function loadState(){try{return JSON.parse(localStorage.getItem(storageKey()))||defaultState()}catch{return defaultState()}}
let state=loadState();
let view=new URL(location.href).searchParams.get('view')||'home',lastFocus;
const save=()=>localStorage.setItem(storageKey(),JSON.stringify(state));
function chooseUser(type){freezeForm=false;userType=['personal','enterprise','authentication','frozen'].includes(type)?type:'enterprise';sessionStorage.setItem('cq-portal-user',userType);state=loadState()}
const pageId=v=>frozen()?(v==='workbench'&&!frozenLocked()?'portal-workbench':'portal-frozen-home'):personal()?(v==='workbench'?'portal-person-workbench':'portal-person-home'):(v==='workbench'?'portal-workbench':'portal-home');
const surface=v=>frozen()?(v==='workbench'&&!frozenLocked()?'portal.identity':'portal.frozen.home'):personal()?(v==='workbench'?'portal.personal.identity':'portal.personal.home'):(v==='workbench'?'portal.identity':'portal.home');
const daysLeft=()=>Math.round((new Date(state.expiry+'T00:00:00+08:00')-today)/day);
const icon=`<span class="brand-icon"><svg viewBox="0 0 24 24" fill="currentColor"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 7v4c0 4 16 4 16 0V7c-3 3-13 3-16 0zm0 7v4c0 4 16 4 16 0v-4c-3 3-13 3-16 0z"/></svg></span>`;
const brand=work=>`<div class="brand">${icon}<span class="portal-system-picker" ${req('portal.system.switch','portal.system.switch.brand')}><select id="portal-system-switch" aria-label="切换门户与管理系统"><option value="portal" selected>区域功能节点（门户）</option><option value="management">管理系统</option></select><span class="portal-switch-chevron" aria-hidden="true">⌄</span></span><span class="location">⌖ 重庆</span></div>`;
function go(v){if(frozenLocked()&&v!=='login')v='home';view=v;const u=new URL(location.href);u.searchParams.set('view',v);u.searchParams.set('user',userType);history.pushState({},'',u);close(true);render();if(v.startsWith('auth-'))window.scrollTo({top:0,behavior:'instant'})}
function toast(t){$('#toast').className='toast';$('#toast').textContent=t;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').className='',2800)}
function render(){if(view==='login')return login();if(frozen()&&(frozenLocked()||view!=='workbench')){view='home';home();if(appeal?.status!=='success'||!appeal.successDismissed)frozenDialog();return}if(view.startsWith('auth-'))return authPage();if(userType==='authentication')return go('auth-entry');if(view==='workbench')return workbench();home()}
function home(){app.innerHTML=`<main class="portal" data-req-page="${pageId('home')}" data-req-surface="${surface('home')}" data-req-title="${profile().label}用户门户首页"><header class="topbar">${brand(false)}<nav class="nav"><a class="active" href="#" data-action="home">首页</a><a href="#" data-action="catalog">数据交易⌄</a><a href="#" data-action="info">应用市场</a><a href="./index.html?system=management">业务节点</a><a href="#" data-action="info">需求广场</a><a href="#" data-action="info">服务支持⌄</a></nav><div class="user"><span class="avatar">●</span><span class="username">${profile().name}</span><span class="tag ${frozen()?'frozen-account-tag':''}">${profile().label}</span><button class="btn small blue" data-action="workbench" ${req('portal.workbench')}>▦ 工作台</button><button class="btn ghost" data-action="logout" ${req('portal.logout')}>退出</button></div></header><div class="orbit"></div><section class="hero"><div class="eyebrow">⬡ 国家数据基础设施 · 重庆枢纽 | 践行“三统一”</div><h1>「重」联千城，「庆」通天下</h1><p>打造西部数据流通走廊</p><div class="principles">统一目录<span>•</span>统一身份<span>•</span>统一接口</div><div class="metrics" ${req('portal.statistics')}><div class="metric" ${req('portal.statistics','portal.stats.entities')}><strong>11</strong><em>家</em><label>入驻主体</label></div><div class="metric" ${req('portal.statistics','portal.stats.nodes')}><strong>3</strong><em>个</em><label>业务节点</label></div><div class="metric" ${req('portal.statistics','portal.stats.resources')}><strong>42</strong><em>个</em><label>数据资源</label></div><div class="metric" ${req('portal.statistics','portal.stats.products')}><strong>291</strong><em>个</em><label>数据产品</label></div></div></section><div class="portal-footer">重庆区域功能节点 · 让数据安全流通，让价值充分释放</div><button class="demo-entry" data-action="demo" ${req('portal.login')}>↗ 登录与续期提醒演示</button></main>`}
const info=(label,value)=>`<div class="info"><label>${label}</label><div>${value}</div></div>`;
function workbench(){app.innerHTML=`<div data-req-page="${pageId('workbench')}" data-req-surface="${surface('workbench')}" data-req-title="${profile().label}身份管理"><header class="topbar">${brand(true)}<button class="return" data-action="home" ${req('portal.workbench','portal.return')}>← 返回门户</button><div class="user"><span class="avatar" style="background:#5747f5;color:white">◉</span>${profile().id}<span class="tag">${profile().label}</span></div></header><div class="workspace"><aside class="sidebar"><div class="side-label">个人中心</div><button class="side-item active">▣　 身份管理</button><button class="side-item" data-action="nodes">♧　 业务节点管理</button><button class="side-item" data-action="info">♜　 连接器管理</button><button class="side-item" data-action="info">♧　 标识解析</button><div class="side-label" style="margin-top:14px">我的资产</div><button class="side-item" data-action="catalog">▤　 数据资源</button><button class="side-item" data-action="catalog">◇　 数据产品</button></aside><div class="content"><h2>▣ 身份管理</h2><section class="section" ${req('identity.details')}><div class="section-head"><h3><span>▥</span>基本信息</h3><div class="actions"><button class="btn small blue" data-action="password">⚿ 修改密码</button><button class="btn small green" data-action="change">▣ 变更</button><button class="btn small purple" data-action="history">◴ 变更记录</button><button class="btn small red" data-action="cancel">▤ 注销</button><button class="btn small orange" data-action="renew" ${req('identity.renew')}>◷ 续期</button></div></div><div class="info-grid">${personal()?personalInfo():enterpriseInfo()}</div><div class="validity" ${req('identity.renew','identity.validity')}><span>主体身份有效期 <strong>180 天</strong></span><span>到期时间 <b>${state.expiry}</b></span>${state.pending?'<span class="pending">● 续期申请审核中</span>':`<span>剩余 <b>${Math.max(0,daysLeft())} 天</b></span>`}</div></section>${personal()?personalDocuments():`<section class="section"><div class="section-head"><h3><span>♟</span>法定代表人/负责人信息</h3></div><div class="info-grid">${info('法定代表人或负责人姓名','王艳波')}${info('法定代表人或负责人证件号','220181198008060421')}${info('法定代表人或负责人手机号','18611740968')}${info('法定代表人或负责人邮箱','-')}${info('法定代表人实名等级','身份证实名核验或社保卡实名核验')}${info('法定代表人实名认证方式','-')}</div></section><section class="section"><div class="section-head"><h3><span>▤</span>注册信息</h3></div><div class="info-grid">${info('注册地址','-')}${info('注册金额（元）','-')}</div></section>`}</div></div></div>`}

