function personalDocuments(){return `<section class="section" ${req('identity.personal.documents')}><div class="section-head"><h3><span>▣</span>证件信息</h3></div><div class="document-grid"><div><label>证件-正面</label><div class="document-card"><svg viewBox="0 0 200 120" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#c7e4e3"/><stop offset="1" stop-color="#f8eed1"/></linearGradient></defs><rect width="200" height="120" fill="url(#sky)"/><path d="M0 65L35 37 68 60 110 31 150 56 200 40V120H0" fill="#8daf9e"/><path d="M0 85L50 62 90 80 140 56 200 75V120H0" fill="#5e9288"/><path d="M0 100H200" stroke="#d3e2dc" stroke-width="4"/><circle cx="92" cy="64" r="6" fill="#314a57"/><path d="M85 75h14v35H85z" fill="#f0e7ca"/><circle cx="113" cy="67" r="6" fill="#695441"/><path d="M105 79h15v31h-15z" fill="#ebd6ae"/></svg></div></div><div><label>证件-反面</label><div class="document-card"><svg viewBox="0 0 200 120" aria-hidden="true"><rect x="54" y="13" width="92" height="96" rx="5" fill="#fcfcfc" stroke="#eef0f5"/><path d="M55 72Q80 58 101 77T145 67V108H55Z" fill="#ffe19a"/><path d="M55 85Q80 60 104 84T145 77V108H55Z" fill="#ffbf32"/></svg></div></div></div></section>`}

function login(){app.innerHTML=`<main class="login-page" data-req-page="portal-login" data-req-surface="portal.login" data-req-title="门户登录"><section class="login-card"><h1>欢迎回来</h1><div class="login-sub">重庆区域功能节点</div><div class="login-account-heading">账号登录</div><form id="login-form" ${req('portal.login')}><div class="field" ${req('portal.login','login.accountType')}><label for="account">账号</label><select class="input account-select" id="account" required><option value="personal" ${personal()?'selected':''}>个人</option><option value="enterprise" ${userType==='enterprise'?'selected':''}>企业</option><option value="authentication" ${userType==='authentication'?'selected':''}>身份认证</option><option value="frozen" ${frozen()?'selected':''}>冻结身份</option></select></div><div class="field" ${req('portal.login','login.password')}><label for="password">密码</label><input class="input" id="password" type="password" value="Demo123456" disabled aria-label="密码（演示，无需填写）"></div><div class="field" ${req('portal.login','login.captcha')}><label for="captcha">验证码</label><div class="captcha-line"><input class="input" id="captcha" value="27" disabled aria-label="验证码（演示，无需填写）"><button type="button" class="captcha" disabled aria-label="验证码图片（不可操作）">9+18=?</button></div></div><p class="login-demo-hint">选择个人、企业、身份认证或冻结身份，进入对应功能。</p><label class="remember"><input type="checkbox" checked>记住我</label><button class="btn primary login-button" type="submit">登录</button><div class="error" id="login-error" role="alert"></div></form><div class="register">还没有账号？<button data-action="register">立即注册</button></div><div class="login-foot">渝ICP备20009072号-1　♜ 渝公网安备 50019002502956号</div></section></main>`}
function show(content){lastFocus=document.activeElement;root.innerHTML=`<div class="mask">${content}</div>`;root.querySelector('button,input')?.focus()}
function close(force=false){if(freezeBlocking&&!force)return;cancelAppealTimer();if(successNoticeOpen&&appeal?.status==='success'){appeal.successDismissed=true;persistAppeal()}successNoticeOpen=false;freezeBlocking=false;app.inert=false;app.removeAttribute('aria-hidden');document.body.style.overflow='';root.innerHTML='';lastFocus?.focus();lastFocus=null}
function modal(title,body,footer,surface='identity.renew'){show(`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" data-req-page="${pageId('workbench')}" data-req-surface="${surface}" data-req-layer="dialog" data-req-title="${title}"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="关闭弹窗">×</button></div>${body}<footer class="dialog-footer">${footer}</footer></section>`)}
function renew(){if(state.pending){return modal('续期申请详情',`<div class="dialog-body"><div class="renew-subject">${profile().label}主体 · ${profile().subject}</div><div class="notice">您的续期申请已提交，正在审核中，请勿重复提交。</div><div class="date-grid"><div><label>申请时间</label><strong>${state.pending.date}</strong></div><div><label>申请续期时长</label><strong>${state.pending.days} 天</strong></div><div><label>首次续期时间</label><strong>${state.firstRenewal||'暂无（首次申请）'}</strong></div><div><label>当前到期时间</label><strong>${state.expiry}</strong></div></div><div class="estimate">审核通过后到期时间<strong>${state.pending.newExpiry}</strong></div></div>`,'<button class="btn primary" data-action="close">我知道了</button>')}
modal('主体身份续期申请',`<form id="renew-form"><div class="dialog-body"><div class="renew-subject">${profile().label}主体 · ${profile().subject}</div><div class="notice">ⓘ 主体身份默认有效期为 180 天，请在到期前申请续期。单次续期最长 360 天，审核通过后生效。</div><div class="date-grid"><div><label>首次续期时间</label><strong>${state.firstRenewal||'暂无'} <small>${state.firstRenewal?'':'（首次申请）'}</small></strong></div><div><label>当前到期时间</label><strong>${state.expiry}</strong></div></div><div class="field" ${req('identity.renew','renew.duration')}><label class="required" for="duration">申请续期时长</label><div class="duration"><input class="input" type="number" id="duration" min="1" max="360" step="1" value="180" required><span>天</span></div><div class="presets"><button type="button" class="active" data-days="180">180 天</button><button type="button" data-days="360">360 天</button></div><p class="hint">请输入 1–360 的整数，默认 180 天。</p></div><div class="estimate" ${req('identity.renew','renew.estimate')}>预计续期后到期时间<strong id="estimated">${fmt(add(state.expiry+'T00:00:00+08:00',180))}</strong></div><p class="hint">未到期从当前到期日顺延；已到期从审核通过日计算。预计日期以审核结果为准。</p><div id="renew-error" class="error" role="alert"></div></div></form>`,`<button class="btn" data-action="close">取消</button><button class="btn primary" type="submit" form="renew-form" ${req('identity.renew','renew.submit')}>提交申请</button>`)}
function remind(){modal('主体身份即将到期',`<div class="reminder" ${req('identity.reminder')}><div class="clock-icon">◷</div><h2>您的主体身份即将到期</h2><p>距离到期还有 <span class="days">${daysLeft()} 天</span>，请及时申请续期<br>保障您的业务持续办理。</p><div class="reminder-details">${personal()?'姓名':'主体名称'}<strong>${profile().subject}</strong><br>到期时间<strong>${state.expiry}</strong><br>续期上限<strong>360 天 / 次</strong></div><p>申请审核通过后生效，请预留审核时间。</p></div>`,`<button class="btn" data-action="close">稍后提醒</button><button class="btn primary" data-action="renew" ${req('identity.reminder','reminder.apply')}>立即申请续期 →</button>`,'identity.reminder')}
function updateEstimate(){const n=Number($('#duration').value);$('#estimated').textContent=Number.isInteger(n)&&n>=1&&n<=360?fmt(add(daysLeft()<0?today:state.expiry+'T00:00:00+08:00',n)):'—';root.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('active',Number(b.dataset.days)===n))}
document.addEventListener('input',e=>{if(e.target.id==='duration')updateEstimate()});
document.addEventListener('click',e=>{const authControl=e.target.closest('[data-auth-action]');if(authControl){e.preventDefault();handleAuth(authControl);return}const preset=e.target.closest('[data-days]');if(preset){$('#duration').value=preset.dataset.days;updateEstimate();return}const a=e.target.closest('[data-action]');if(!a)return;e.preventDefault();if(frozenLocked()&&view!=='login')return;switch(a.dataset.action){case'home':go('home');break;case'workbench':go('workbench');break;case'logout':if(frozen())resetAppeal();go('login');break;case'demo':go('login');break;case'renew':renew();break;case'close':close();break;case'nodes':location.href='./index.html';break;case'catalog':location.href='./index.html?view=catalog';break;case'history':modal('变更记录','<div class="dialog-body"><div class="notice">暂无主体信息变更记录。</div></div>','<button class="btn primary" data-action="close">关闭</button>','identity.history');break;case'captcha':$('#captcha').value='';a.textContent='9+18=?';$('#captcha').focus();break;case'download':toast('演示环境暂无可下载的真实证书');break;default:toast('当前原型聚焦身份续期流程，该功能暂未展开。')}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();chooseUser($('#account').value);if(frozen())resetAppeal();if(userType==='authentication'){go('auth-entry');return}go('home');if(frozen())return;if(daysLeft()>=0&&daysLeft()<=7&&!state.pending)remind();else if(daysLeft()<0)toast('主体身份已到期，请进入工作台申请续期。')}if(e.target.id==='renew-form'){e.preventDefault();const n=Number($('#duration').value);if(!Number.isInteger(n)||n<1||n>360){$('#renew-error').textContent='续期时长必须为 1–360 的整数。';return}if(state.pending)return;state.pending={date:fmt(today),days:n,newExpiry:fmt(add(daysLeft()<0?today:state.expiry+'T00:00:00+08:00',n))};save();close();render();modal('续期申请已提交',`<div class="reminder"><div class="clock-icon success-icon">✓</div><h2>申请提交成功</h2><p>您的主体身份续期申请正在审核中。<br>审核通过后生效，当前到期时间保持不变。</p><div class="reminder-details">申请续期时长<strong>${n} 天</strong><br>预计新到期时间<strong>${state.pending.newExpiry}</strong><br>申请状态<strong>待审核</strong></div></div>`,'<button class="btn primary" data-action="close">完成</button>','identity.renew.result')}});
document.addEventListener('keydown',e=>{if(!root.children.length)return;if(e.key==='Escape'){if(freezeBlocking){e.preventDefault();e.stopPropagation();return}close();return}if(e.key==='Tab'){const els=[...root.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(!first){e.preventDefault();root.querySelector('[role="dialog"]')?.focus();return}if(freezeBlocking&&!root.contains(document.activeElement)){e.preventDefault();(e.shiftKey?last:first).focus();return}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let authStage='review';
const authPerson=()=>view==='auth-personal';
const authShield=`<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2 3.5 5.5v5.8c0 5.1 3.7 8.8 8.5 10.7 4.8-1.9 8.5-5.6 8.5-10.7V5.5L12 2Zm0 3 5.5 2.3v4c0 3.5-2.3 6.4-5.5 8V5Z"/></svg>`;
const authPersonIcon=`<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3H4Z"/></svg>`;
const authCompanyIcon=`<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M4 22V2h12v6h4v14H4Zm3-4h2v-3H7v3Zm0-6h2V9H7v3Zm0-6h2V4H7v2Zm5 12h2v-3h-2v3Zm0-6h2V9h-2v3Zm0-6h2V4h-2v2Zm5 12h1v-3h-1v3Zm0-6h1v-2h-1v2Z"/></svg>`;
function authHeader(){return `<header class="topbar">${brand(true)}<button class="return" data-auth-action="${view==='auth-entry'?'login':'back'}" ${req('portal.auth.entry','auth.back')}>← ${view==='auth-entry'?'返回登录':view==='auth-types'?'返回身份管理':'返回认证类型'}</button><div class="user"><span class="avatar">◉</span>体验账号<span class="tag auth-unverified">未认证</span><button class="btn" data-action="logout" ${req('portal.logout','auth.logout')}>退出</button></div></header>`}
function authPage(){let content,title,surf,page;
 if(view==='auth-entry'){title='主体身份认证';surf='portal.auth.entry';page='portal-auth-entry';content=`<div class="auth-entry-space"><section class="auth-entry-card" ${req('portal.auth.entry')}><div class="auth-symbol">${authShield}</div><h1>主体身份认证</h1><p>您尚未完成主体身份认证，认证后方可管理身份信息与数字凭证</p><button class="auth-entry-button" data-auth-action="types" ${req('portal.auth.entry','auth.start')}>去主体认证 <span>→</span></button></section></div>`}
 else if(view==='auth-types'){title='选择认证类型';surf='portal.auth.types';page='portal-auth-types';content=`<div class="auth-type-heading"><span class="auth-kicker">主体身份认证</span><h1>选择您的身份认证类型</h1><p>请选择与您主体身份一致的认证类型</p></div><div class="auth-type-grid">${[['personal','个人认证','适用于个人用户，参与数据共享与价值交换',authPersonIcon,['个人身份信息认证','个人数据资产管理','参与数据交易市场','个人隐私数据保护']],['enterprise','企业认证','适用于企业用户，可选择法定代表人认证或经办人认证',authCompanyIcon,['企业工商信息认证','法人 / 经办人身份认证','企业数据资产确权','企业数据合规管理']]].map(([type,name,description,symbol,items])=>`<section class="auth-type-card ${type==='personal'?'auth-type-personal':''}" ${req('portal.auth.types','auth.type.'+type)}><div class="auth-symbol">${symbol}</div><h2>${name}</h2><p>${description}</p><ul>${items.map(x=>`<li><span>✓</span>${x}</li>`).join('')}</ul><button class="btn primary" data-auth-action="${type}" ${req('portal.auth.types','auth.select.'+type)}>选择此类型 <span>→</span></button></section>`).join('')}</div>`}
 else{const isPerson=authPerson();title=isPerson?'个人身份认证':'企业身份认证';surf=isPerson?'portal.auth.personal.review':'portal.auth.enterprise.review';page=isPerson?'portal-auth-personal':'portal-auth-enterprise';content=authReview(isPerson)}
 app.innerHTML=`<div class="auth-shell" data-req-page="${page}" data-req-surface="${surf}" data-req-title="${title}${view==='auth-personal'||view==='auth-enterprise'?' · '+(authStage==='review'?'认证审核中':'已提交信息'):''}">${authHeader()}<main class="auth-main ${view==='auth-entry'?'auth-entry-main':''}">${content}</main></div>`}
function authSteps(isPerson){const labels=isPerson?['基本信息','认证审核中']:['选择类型','基本信息','认证审核中'];return `<nav class="auth-steps" aria-label="认证进度">${labels.map((name,i)=>{const chosen=name===(authStage==='review'?'认证审核中':'基本信息'),interactive=name==='认证审核中',tag=interactive?'button':'div';return `<${tag} class="auth-step ${chosen?'current':name==='认证审核中'?'':'completed'}" ${chosen?'aria-current="step"':''} ${interactive?'data-auth-action="review"':''} ${req(isPerson?'portal.auth.personal.review':'portal.auth.enterprise.review','auth.'+(isPerson?'personal':'enterprise')+'.step.'+i)}><span class="auth-step-number">${chosen?i+1:name==='认证审核中'?i+1:'✓'}</span><span>${name}</span></${tag}>`}).join('')}</nav>`}
function authInfoBlock(title,rows,rid){return `<section class="auth-info-card" ${req(rid)}><h2><span>▣</span>${title}</h2><dl class="auth-info-grid">${rows.map(([label,value,wide])=>`<div class="${wide?'wide':''}"><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl></section>`}
function authMaterialBlock(title,names,rid){return `<section class="auth-info-card" ${req(rid,'auth.materials.'+({'电子营业执照':'license','证件照片':'photos','法人身份证':'legal.id','补充材料':'supplements','证书请求文件 CSR':'csr'}[title]||'other')+'.'+(authPerson()?'personal':'enterprise'))}><h2><span>▤</span>${title}</h2><div class="auth-material-grid">${names.map(([label,file])=>`<div class="auth-material"><div class="auth-file-icon">${file.endsWith('.csr')?'CSR':file.endsWith('.pdf')?'PDF':'IMG'}</div><div><strong>${label}</strong><small>${file}</small><span class="auth-file-status">✓ 已提交</span></div><button class="auth-file-view" data-auth-action="material" data-auth-file="${label}" data-auth-filename="${file}" ${req('portal.auth.materials','auth.file.'+file.replace(/[^a-z0-9]/gi,'.'))}>查看</button></div>`).join('')}</div></section>`}
function authReview(isPerson){const rid=isPerson?'portal.auth.personal.review':'portal.auth.enterprise.review',infoRid=isPerson?'portal.auth.personal.info':'portal.auth.enterprise.info';const code='CQ-'+(isPerson?'P':'E')+'-'+fmt(today).replaceAll('-','')+'-001',submitted=fmt(add(today,-1))+' 10:20:00';
 const personalRows=[['姓名','王三'],['证件类型','中华人民共和国居民身份证'],['证件号码','500228199505070116'],['证件有效期','2019-07-02 至 2035-07-02'],['证书请求文件 CSR','客户端生成'],['申请状态','<span class="auth-state-tag">● 认证审核中</span>']];
 const enterpriseRows=[['企业全称','重庆壹弘科技有限公司'],['法人或其他组织类型','企事业单位法人'],['统一社会信用代码','91500103MAE2CF7R62'],['经营期限','2024-10-30 至 长期'],['认证方式','法定代表人认证'],['申请状态','<span class="auth-state-tag">● 认证审核中</span>']];
 const metadata=`<div class="auth-application-meta"><div><span>申请编号</span><strong>${code}</strong></div><div><span>提交时间</span><strong>${submitted}</strong></div><div><span>认证类型</span><strong>${isPerson?'个人认证':'企业认证 · 法定代表人认证'}</strong></div></div>`;
 const status=`<section class="auth-pending-card" ${req(rid)}><div class="auth-pending-top"><div class="auth-pending-icon"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><circle cx="16" cy="16" r="11" stroke="currentColor" stroke-width="2.4"/><path d="M16 9v8l5 3" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg></div><div><div class="auth-pending-eyebrow">申请已成功提交</div><h1>身份认证审核中</h1><p>您的${isPerson?'个人':'企业'}认证信息已提交，工作人员正在审核，请耐心等待。</p></div></div>${metadata}</section>`;
 let details=authInfoBlock(isPerson?'个人信息':'企业信息',isPerson?personalRows:enterpriseRows,infoRid);
 if(!isPerson){details+=authMaterialBlock('电子营业执照',[['电子营业执照','business-license.jpg']],'portal.auth.materials');details+=authInfoBlock('企业附加信息',[['注册地址','重庆市渝中区示例路 88 号'],['注册金额（元）','1,000,000.00'],['注册日期','2024-10-30'],['行业类型','软件和信息技术服务业'],['经营范围','软件开发、信息技术咨询服务、数据处理服务。',true]],infoRid);details+=authInfoBlock('法定代表人信息',[['法人姓名','王艳波'],['法人身份证号','220181198008060421'],['法人邮箱','未提供']],infoRid);details+=authInfoBlock('补充信息',[['主体资质信息','相关资质信息及证明材料已随申请提交。',true],['业务对接信息','对接人：王艳波；联系电话：18611740968。',true],['主体授权信息','由法定代表人发起认证，授权范围为主体身份认证。',true]],infoRid)}
 details+=authMaterialBlock(isPerson?'证件照片':'法人身份证',isPerson?[['证件正面','personal-id-front.jpg'],['证件反面','personal-id-back.jpg']]:[['身份证正面','legal-id-front.jpg'],['身份证反面','legal-id-back.jpg']],'portal.auth.materials');
 if(!isPerson)details+=authMaterialBlock('补充材料',[['授权文件证明材料','authorization.pdf'],['资质证书证明材料','qualification.pdf']],'portal.auth.materials');
 details+=authMaterialBlock('证书请求文件 CSR',[[isPerson?'个人 CSR 文件':'企业 CSR 文件',isPerson?'personal-identity.csr':'enterprise-identity.csr']],'portal.auth.materials');
 return `<div class="auth-review-heading"><div><span class="auth-kicker">主体身份认证</span><h2>${isPerson?'个人身份认证':'企业身份注册'}</h2></div></div><div class="auth-review-sheet">${authSteps(isPerson)}${status}<div class="auth-section-heading"><div><h2>已提交的认证信息</h2><p>信息与材料已锁定，审核期间无需重复提交。</p></div></div>${details}</div>`}
function handleAuth(button){switch(button.dataset.authAction){case'login':go('login');break;case'back':go(view==='auth-types'?'auth-entry':'auth-types');break;case'types':go('auth-types');break;case'personal':authStage='review';go('auth-personal');break;case'enterprise':authStage='review';go('auth-enterprise');break;case'review':authStage='review';authPage();window.scrollTo({top:0,behavior:'instant'});break;case'material':{const name=button.dataset.authFile,file=button.dataset.authFilename;modal('认证材料 · '+name,`<div class="dialog-body"><div class="auth-material-preview">${authShield}<strong>${name}</strong><span>${file}</span><p>已提交 · 审核中</p></div><div class="notice">本原型使用演示认证资料；此处为材料查看示意。审核期间不可替换、删除或重新上传。</div></div>`,'<button class="btn primary" data-action="close">关闭</button>','portal.auth.material.preview');const dialog=root.querySelector('[role="dialog"]');if(dialog){dialog.dataset.reqPage=authPerson()?'portal-auth-personal':'portal-auth-enterprise';dialog.dataset.reqId='portal.auth.materials';dialog.dataset.reqElement='auth.material.preview'}break}}}
const safeText=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cancelAppealTimer(){clearTimeout(appealTimer);appealTimer=null;appealTimerEpoch++}
function persistAppeal(){try{if(appeal)localStorage.setItem(appealStorageKey,JSON.stringify(appeal))}catch{}}
function resetAppeal(){cancelAppealTimer();appeal=null;freezeForm=false;successNoticeOpen=false;appealDraft={reason:'',phone:'18611740968'};try{localStorage.removeItem(appealStorageKey)}catch{}}
function armAppealTimer(){cancelAppealTimer();if(!frozen()||view==='login'||!appeal)return;const epoch=appealTimerEpoch,id=appeal.id;
 if(appeal.status==='pending'){if(!Number.isFinite(appeal.pendingUntil)){appeal.pendingUntil=Date.now()+3000;persistAppeal()}appealTimer=setTimeout(()=>{if(epoch!==appealTimerEpoch||!frozen()||view==='login'||appeal?.id!==id||appeal.status!=='pending')return;appeal={...appeal,status:'success',completedAt:Date.now(),successDismissed:false};persistAppeal();home();frozenDialog()},Math.max(0,appeal.pendingUntil-Date.now()))}
}
function frozenDialog(){
 const success=appeal?.status==='success',pending=appeal?.status==='pending',form=freezeForm&&!pending&&!success,title=success?'申诉成功':pending?'解冻申诉中':form?'申请解冻主体身份':'您的主体身份已冻结';
 const data=`<div class="frozen-subject"><div><span>主体名称</span><strong>${profile().subject}</strong></div><div><span>主体身份标识</span><strong>${profile().id}</strong></div></div>`;
 let body,footer;
 if(success){body=`<div class="frozen-state-icon appeal-success">✓</div><h2>申诉成功</h2><p class="frozen-description">您的解冻申诉已通过，主体身份已恢复可用。<br>您可以继续办理业务。</p>${data}<div class="appeal-result"><div><span>申诉编号</span><strong>${safeText(appeal.id)}</strong></div><div><span>处理结果</span><strong class="appeal-success-text">解冻成功</strong></div></div><p class="appeal-auto-close">请点击“我知道了”或右上角关闭按钮，手动关闭此弹窗。</p>`;footer=`<button class="btn primary" data-frozen-action="dismiss-success" ${req('portal.frozen.success','frozen.success.confirm')}>我知道了</button>`}
 else if(pending){body=`<div class="frozen-state-icon appeal-pending">◷</div><h2>申诉中</h2><p class="frozen-description">您的解冻申诉已提交，正在审核中，请耐心等待。</p>${data}<div class="appeal-result"><div><span>申诉编号</span><strong>${safeText(appeal.id)}</strong></div><div><span>提交时间</span><strong>${safeText(appeal.submittedAt)}</strong></div><div><span>联系电话</span><strong>${safeText(appeal.phone)}</strong></div><div class="appeal-reason"><span>申诉说明</span><p>${safeText(appeal.reason)}</p></div></div><div class="frozen-notice">审核完成前，主体身份仍为冻结状态。请勿重复提交申诉。</div>`;footer='<button class="btn primary" disabled>◷ 申诉中</button>'}
 else if(form){body=`<p class="frozen-description frozen-form-description">请填写解冻申诉说明，提交后由工作人员审核。</p>${data}<form id="appeal-form" ${req('portal.frozen.appeal')}><div class="field" ${req('portal.frozen.appeal','frozen.appeal.reason')}><label class="required" for="appeal-reason">申诉说明</label><textarea class="input" id="appeal-reason" rows="4" maxlength="500" required placeholder="请说明申请解冻的原因及相关情况">${safeText(appealDraft.reason)}</textarea><p class="hint">必填，最多 500 字。</p></div><div class="field" ${req('portal.frozen.appeal','frozen.appeal.phone')}><label class="required" for="appeal-phone">联系电话</label><input class="input" id="appeal-phone" type="tel" inputmode="tel" maxlength="11" pattern="1[3-9][0-9]{9}" value="${safeText(appealDraft.phone)}" required autocomplete="tel"><p class="hint">用于申诉审核联系，请填写 11 位手机号码。</p></div><div class="error" id="appeal-error" role="alert"></div></form>`;footer=`<button class="btn primary" type="submit" form="appeal-form" ${req('portal.frozen.appeal','frozen.appeal.submit')}>提交解冻申诉</button>`}
 else{body=`<div class="frozen-state-icon">${authShield}</div><h2>主体身份已冻结</h2><p class="frozen-description">当前主体身份暂不可用，请提交解冻申诉。<br>完成审核并解冻后，方可继续办理业务。</p>${data}<div class="frozen-notice">请先申请解冻。当前提示不可关闭，暂无法进入工作台或办理其他业务。</div>`;footer=`<button class="btn primary" data-frozen-action="appeal" ${req('portal.frozen.appeal','frozen.appeal.start')}>去申诉解冻 →</button>`}
 show(`<section class="dialog frozen-dialog ${success?'frozen-success':pending?'frozen-pending':''} ${form?'frozen-form':''}" role="dialog" aria-modal="true" aria-labelledby="frozen-dialog-title" tabindex="-1" data-req-page="portal-frozen-home" data-req-surface="${success?'portal.frozen.success':pending?'portal.frozen.pending':form?'portal.frozen.appeal':'portal.frozen.blocked'}" data-req-layer="dialog" data-req-title="${title}" ${req(success?'portal.frozen.success':pending?'portal.frozen.pending':form?'portal.frozen.appeal':'portal.frozen.blocked')}><div class="dialog-head"><h2 id="frozen-dialog-title">${title}</h2>${success?`<button class="close" data-frozen-action="dismiss-success" aria-label="关闭申诉成功弹窗" ${req('portal.frozen.success','frozen.success.close')}>×</button>`:`<span class="frozen-status">${pending?'申诉中':'身份冻结'}</span>`}</div><div class="dialog-body">${body}</div><footer class="dialog-footer">${footer}</footer></section>`);
 freezeBlocking=!success;successNoticeOpen=success;app.inert=true;app.setAttribute('aria-hidden','true');document.body.style.overflow='hidden';root.querySelector('button:not([disabled]),textarea,input:not([disabled])')?.focus();if(pending)root.querySelector('[role="dialog"]')?.focus();armAppealTimer();
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-frozen-action]');if(!button||!frozen()||view==='login')return;e.preventDefault();if(button.dataset.frozenAction==='dismiss-success'&&appeal?.status==='success'){close();return}if(button.dataset.frozenAction==='appeal'&&!appeal){freezeForm=true;frozenDialog()}});
document.addEventListener('pointerdown',e=>{if(!freezeBlocking||e.target!==root.querySelector('.mask'))return;e.preventDefault();(root.querySelector('button:not([disabled]),textarea,input:not([disabled])')||root.querySelector('[role="dialog"]'))?.focus()});
document.addEventListener('input',e=>{if(e.target.id==='appeal-reason')appealDraft.reason=e.target.value;if(e.target.id==='appeal-phone')appealDraft.phone=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id!=='appeal-form')return;e.preventDefault();if(!frozen()||view==='login'||appeal?.status==='pending')return;const reason=$('#appeal-reason').value.trim(),phone=$('#appeal-phone').value.trim(),error=$('#appeal-error');if(!reason||reason.length>500){error.textContent='请填写 1–500 字的申诉说明。';$('#appeal-reason').focus();return}if(!/^1[3-9]\d{9}$/.test(phone)){error.textContent='请填写正确的 11 位手机号码。';$('#appeal-phone').focus();return}const record={status:'pending',pendingUntil:Date.now()+3000,id:'AP-CQ-'+fmt(today).replaceAll('-','')+'-'+String(Date.now()).slice(-6),subjectId:profile().id,subjectName:profile().subject,reason,phone,submittedAt:fmt(today)+' '+new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})};try{localStorage.setItem(appealStorageKey,JSON.stringify(record))}catch{error.textContent='申诉保存失败，请重试。';return}appeal=record;freezeForm=false;frozenDialog()});
document.addEventListener('change',e=>{if(e.target.id!=='portal-system-switch'||e.target.value!=='management')return;if(frozenLocked()&&view!=='login'){e.target.value='portal';return}cancelAppealTimer();const target=new URL('./index.html',location.href);target.searchParams.set('portalUser',userType);target.searchParams.set('portalView',view);target.searchParams.set('portalDocument',location.pathname.endsWith('/portal-standalone.html')?'portal-standalone.html':'portal.html');location.href=target.href});
window.addEventListener('popstate',()=>{view=new URL(location.href).searchParams.get('view')||'home';chooseUser(selectedType());close(true);render()});render();
